## 最佳实践

1. **使用 MVVM 模式**：分离 UI 和业务逻辑
2. **依赖注入**：管理服务生命周期
3. **平台抽象**：通过接口隔离平台差异
4. **资源管理**：统一管理图片、字体、样式
5. **性能优化**：使用 CollectionView、懒加载

using System;
using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows.Input;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Maui;
using Microsoft.Maui.Controls;

namespace MAUIDemo
{
    // Model
    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public decimal Price { get; set; }
        public string Description { get; set; }
        public string ImageUrl { get; set; }
    }

    // ObservableObject 基类
    public class ObservableObject : INotifyPropertyChanged
    {
        public event PropertyChangedEventHandler PropertyChanged;

        protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        }

        protected bool SetProperty<T>(ref T field, T value, [CallerMemberName] string propertyName = null)
        {
            if (EqualityComparer<T>.Default.Equals(field, value))
                return false;

            field = value;
            OnPropertyChanged(propertyName);
            return true;
        }
    }

    // AsyncCommand
    public class AsyncCommand : ICommand
    {
        private readonly Func<Task> _execute;
        private readonly Func<bool> _canExecute;
        private bool _isExecuting;

        public AsyncCommand(Func<Task> execute, Func<bool> canExecute = null)
        {
            _execute = execute;
            _canExecute = canExecute;
        }

        public event EventHandler CanExecuteChanged;

        public bool CanExecute(object parameter) => !_isExecuting && (_canExecute?.Invoke() ?? true);

        public async void Execute(object parameter)
        {
            if (_isExecuting)
                return;

            _isExecuting = true;
            CanExecuteChanged?.Invoke(this, EventArgs.Empty);

            try
            {
                await _execute();
            }
            finally
            {
                _isExecuting = false;
                CanExecuteChanged?.Invoke(this, EventArgs.Empty);
            }
        }
    }

    // ViewModels
    public class MainViewModel : ObservableObject
    {
        private readonly IProductService _productService;
        private bool _isBusy;

        public MainViewModel(IProductService productService)
        {
            _productService = productService;
            Products = new ObservableCollection<Product>();
            LoadProductsCommand = new AsyncCommand(LoadProductsAsync);
            RefreshCommand = new AsyncCommand(LoadProductsAsync);
        }

        public ObservableCollection<Product> Products { get; }

        public bool IsBusy
        {
            get => _isBusy;
            set => SetProperty(ref _isBusy, value);
        }

        public ICommand LoadProductsCommand { get; }
        public ICommand RefreshCommand { get; }

        private async Task LoadProductsAsync()
        {
            if (IsBusy)
                return;

            IsBusy = true;

            try
            {
                var products = await _productService.GetProductsAsync();
                Products.Clear();
                foreach (var product in products)
                {
                    Products.Add(product);
                }
            }
            finally
            {
                IsBusy = false;
            }
        }
    }

    public class ProductDetailViewModel : ObservableObject, IQueryAttributable
    {
        private readonly IProductService _productService;
        private Product _product;

        public ProductDetailViewModel(IProductService productService)
        {
            _productService = productService;
        }

        public Product Product
        {
            get => _product;
            set => SetProperty(ref _product, value);
        }

        public void ApplyQueryAttributes(IDictionary<string, object> query)
        {
            if (query.ContainsKey("id"))
            {
                var id = int.Parse(query["id"].ToString());
                LoadProduct(id);
            }
        }

        private async void LoadProduct(int id)
        {
            Product = await _productService.GetProductAsync(id);
        }
    }

    // Services
    public interface IProductService
    {
        Task<IEnumerable<Product>> GetProductsAsync();
        Task<Product> GetProductAsync(int id);
    }

    public class ProductService : IProductService
    {
        private readonly HttpClient _httpClient;

        public ProductService(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task<IEnumerable<Product>> GetProductsAsync()
        {
            return await _httpClient.GetFromJsonAsync<IEnumerable<Product>>("/api/products");
        }

        public async Task<Product> GetProductAsync(int id)
        {
            return await _httpClient.GetFromJsonAsync<Product>($"/api/products/{id}");
        }
    }

    // Platform Service
    public interface IPlatformService
    {
        string GetPlatformName();
        Task<bool> RequestCameraPermissionAsync();
    }

#if ANDROID
    public class AndroidPlatformService : IPlatformService
    {
        public string GetPlatformName() => "Android";

        public async Task<bool> RequestCameraPermissionAsync()
        {
            var status = await Permissions.CheckStatusAsync<Permissions.Camera>();
            if (status != PermissionStatus.Granted)
            {
                status = await Permissions.RequestAsync<Permissions.Camera>();
            }
            return status == PermissionStatus.Granted;
        }
    }
#elif IOS
    public class iOSPlatformService : IPlatformService
    {
        public string GetPlatformName() => "iOS";

        public async Task<bool> RequestCameraPermissionAsync()
        {
            var status = await Permissions.CheckStatusAsync<Permissions.Camera>();
            if (status != PermissionStatus.Granted)
            {
                status = await Permissions.RequestAsync<Permissions.Camera>();
            }
            return status == PermissionStatus.Granted;
        }
    }
#else
    public class DefaultPlatformService : IPlatformService
    {
        public string GetPlatformName() => "Unknown";

        public Task<bool> RequestCameraPermissionAsync() => Task.FromResult(false);
    }
#endif

    // Views
    public partial class MainPage : ContentPage
    {
        public MainPage(MainViewModel viewModel)
        {
            InitializeComponent();
            BindingContext = viewModel;
        }

        protected override void OnAppearing()
        {
            base.OnAppearing();
            if (BindingContext is MainViewModel viewModel)
            {
                viewModel.LoadProductsCommand.Execute(null);
            }
        }
    }

    public partial class ProductDetailPage : ContentPage
    {
        public ProductDetailPage(ProductDetailViewModel viewModel)
        {
            InitializeComponent();
            BindingContext = viewModel;
        }
    }

    // App Configuration
    public static class MauiProgram
    {
        public static MauiApp CreateMauiApp()
        {
            var builder = MauiApp.CreateBuilder();
            builder
                .UseMauiApp<App>()
                .ConfigureFonts(fonts =>
                {
                    fonts.AddFont("OpenSans-Regular.ttf", "OpenSansRegular");
                    fonts.AddFont("OpenSans-Semibold.ttf", "OpenSansSemibold");
                });

            // 注册 HttpClient
            builder.Services.AddHttpClient<IProductService, ProductService>(client =>
            {
                client.BaseAddress = new Uri("https://api.example.com");
            });

            // 注册平台服务
            builder.Services.AddSingleton<IPlatformService>(provider =>
            {
#if ANDROID
                return new AndroidPlatformService();
#elif IOS
                return new iOSPlatformService();
#else
                return new DefaultPlatformService();
#endif
            });

            // 注册页面和 ViewModel
            builder.Services.AddTransient<MainPage>();
            builder.Services.AddTransient<MainViewModel>();
            builder.Services.AddTransient<ProductDetailPage>();
            builder.Services.AddTransient<ProductDetailViewModel>();

            return builder.Build();
        }
    }

    // App.xaml.cs
    public partial class App : Application
    {
        public App()
        {
            InitializeComponent();

            // 注册路由
            Routing.RegisterRoute("productDetail", typeof(ProductDetailPage));

            MainPage = new AppShell();
        }
    }

    // AppShell.xaml.cs
    public partial class AppShell : Shell
    {
        public AppShell()
        {
            InitializeComponent();
        }
    }
}
